class Frame(NamedTuple):
    """One accepted frame: its type, its raw bytes (start..crc) and the decoded packet."""
    type: PacketType
    raw: bytes
    packet: Packet


class Deframer:
    """Streaming deframer for all four packet types, same rules as ds_deframer_feed():
    a frame is accepted only with one of the four start bytes, that type's exact len and a
    matching CRC; on any mismatch only the first held byte is dropped and the search restarts
    at the next byte. Bytes outside accepted frames are junk (on the USB port: debug text).
    Results do not depend on how the stream is split into feed() calls.
    accept_legacy=True also accepts each packet's older layouts at their exact lengths
    (LEGACY: an older RA4M1 build's TelemetryPacket); ds_deframer_feed() never does.
    """

    def __init__(self, accept_legacy: bool = False) -> None:
        self.accept_legacy = accept_legacy
        self._buf = bytearray()
        self.frames = 0
        self.crc_errors = 0
        self.len_errors = 0
        self.junk_bytes = 0

    @property
    def held(self) -> int:
        """Bytes held: a strict prefix of a possible frame, waiting for more input."""
        return len(self._buf)

    def reset(self) -> None:
        self._buf.clear()

    def feed_ordered(self, data) -> List[Union[Frame, bytes]]:
        """Frames and junk runs (bytes) in stream order. Junk is reported once resolved:
        a held prefix of a possible frame is reported by a later call."""
        buf = self._buf
        buf += data
        items: List[Union[Frame, bytes]] = []
        i = 0          # first unresolved byte
        junk_from = 0  # [junk_from, i) is resolved junk not yet reported
        n = len(buf)
        while i < n:
            cls = _BY_START.get(buf[i])
            if cls is None:
                m = _START_RE.search(buf, i + 1)
                i = m.start() if m else n
                continue
            if n - i < DS_FRAME_HEADER_LEN:
                break
            length = buf[i + 1]
            if length != cls.LEN and not (self.accept_legacy and length in cls.LEGACY):
                self.len_errors += 1
                i += 1
                continue
            end = i + length + DS_FRAME_OVERHEAD
            if end > n:
                break
            if crc8(buf[i + 1:end - 1]) != buf[end - 1]:
                self.crc_errors += 1
                i += 1
                continue
            if junk_from < i:
                items.append(bytes(buf[junk_from:i]))
                self.junk_bytes += i - junk_from
            raw = bytes(buf[i:end])
            items.append(Frame(cls.TYPE, raw, cls.from_payload(raw[DS_FRAME_HEADER_LEN:-1])))
            self.frames += 1
            i = junk_from = end
        if junk_from < i:
            items.append(bytes(buf[junk_from:i]))
            self.junk_bytes += i - junk_from
        del buf[:i]
        return items

    def feed(self, data) -> List[Frame]:
        """Only the frames completed by data, in order."""
        return [item for item in self.feed_ordered(data) if isinstance(item, Frame)]
